22→      description:
23→        "You've been wrongfully imprisoned. You have one hour to find the hidden escape route before the guards return.",
24→      difficulty: "Hard",
25→      maxPlayers: 8,
26→    },
27→    {
28→      name: "The Lost Temple",
29→      description:
30→        "Deep in the jungle, an ancient temple holds untold secrets. Navigate its traps and puzzles to claim the treasure.",
31→      difficulty: "Easy",
32→      maxPlayers: 4,
33→    },
34→  ];
35→
36→  // Create rooms with hourly time slots for tomorrow
37→  const tomorrow = new Date();
38→  tomorrow.setDate(tomorrow.getDate() + 1);
39→  tomorrow.setHours(10, 0, 0, 0);
40→
41→  for (const roomData of rooms) {
42→    const room = await prisma.room.create({ data: roomData });
43→
44→    // Create hourly slots from 10 AM to 5 PM (7 slots)
45→    for (let hour = 0; hour < 7; hour++) {
46→      const startTime = new Date(tomorrow);
47→      startTime.setHours(10 + hour);
48→
49→      const endTime = new Date(startTime);
50→      endTime.setHours(startTime.getHours() + 1);
51→
52→      await prisma.timeSlot.create({
53→        data: {
54→          roomId: room.id,
55→          startTime,
56→          endTime,
57→        },
58→      });
59→    }
60→  }
61→
62→  console.log("Seeded 3 rooms with 7 time slots each (21 total).");
63→}
