 1→import { Hold, PrismaClient } from "@prisma/client";
 2→
 3→export function isHoldExpired(hold: Hold): boolean {
 4→  return new Date() > hold.expiresAt;
 5→}
 6→
 7→export async function cleanupExpiredHold(
 8→  prisma: PrismaClient,
 9→  timeSlotId: string
10→): Promise<boolean> {
11→  const hold = await prisma.hold.findUnique({ where: { timeSlotId } });
12→  if (hold && isHoldExpired(hold)) {
13→    await prisma.hold.delete({ where: { id: hold.id } });
14→    return true;
15→  }
16→  return false;
17→}
