 5→export async function GET() {
 6→  const rooms = await prisma.room.findMany({
 7→    include: {
 8→      timeSlots: {
 9→        include: {
10→          hold: true,
11→          booking: true,
12→        },
13→        orderBy: { startTime: "asc" },
14→      },
15→    },
16→    orderBy: { name: "asc" },
17→  });
18→
19→  const result = rooms.map((room) => ({
20→    id: room.id,
21→    name: room.name,
22→    description: room.description,
23→    difficulty: room.difficulty,
24→    maxPlayers: room.maxPlayers,
25→    timeSlots: room.timeSlots.map((slot) => {
26→      let status: "available" | "held" | "booked";
27→      if (slot.booking) {
28→        status = "booked";
29→      } else if (slot.hold && !isHoldExpired(slot.hold)) {
30→        status = "held";
31→      } else {
32→        status = "available";
33→      }
34→
35→      return {
36→        id: slot.id,
37→        startTime: slot.startTime,
38→        endTime: slot.endTime,
39→        status,
40→      };
41→    }),
42→  }));
43→
44→  return NextResponse.json(result);
45→}
