 1→import { NextRequest, NextResponse } from "next/server";
 2→import { prisma } from "@/lib/prisma";
 3→import { HOLD_DURATION_MS } from "@/lib/constants";
 4→import { isHoldExpired } from "@/lib/holds";
 5→import { Prisma } from "@prisma/client";
 6→
 7→export async function POST(request: NextRequest) {
 8→  let body: { timeSlotId?: string; playerName?: string; playerEmail?: string };
 9→  try {
10→    body = await request.json();
11→  } catch {
12→    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
13→  }
14→
15→  const { timeSlotId, playerName, playerEmail } = body;
16→
17→  if (!timeSlotId || !playerName || !playerEmail) {
18→    return NextResponse.json(
19→      { error: "timeSlotId, playerName, and playerEmail are required" },
20→      { status: 400 }
21→    );
22→  }
23→
24→  try {
25→    const hold = await prisma.$transaction(async (tx) => {
26→      const timeSlot = await tx.timeSlot.findUnique({
27→        where: { id: timeSlotId },
28→        include: { booking: true, hold: true },
29→      });
30→
31→      if (!timeSlot) {
32→        throw new HoldError(404, "Time slot not found");
33→      }
34→
35→      if (timeSlot.booking) {
36→        throw new HoldError(409, "Time slot is already booked");
37→      }
38→
39→      if (timeSlot.hold) {
40→        if (isHoldExpired(timeSlot.hold)) {
41→          await tx.hold.delete({ where: { id: timeSlot.hold.id } });
42→        } else {
43→          throw new HoldError(409, "Time slot is already held");
44→        }
45→      }
46→
47→      return tx.hold.create({
48→        data: {
49→          timeSlotId,
50→          playerName,
51→          playerEmail,
52→          expiresAt: new Date(Date.now() + HOLD_DURATION_MS),
53→        },
54→      });
55→    });
56→
57→    return NextResponse.json(hold, { status: 201 });
58→  } catch (error) {
59→    if (error instanceof HoldError) {
60→      return NextResponse.json(
61→        { error: error.message },
62→        { status: error.status }
63→      );
64→    }
65→
66→    if (
67→      error instanceof Prisma.PrismaClientKnownRequestError &&
68→      error.code === "P2002"
69→    ) {
70→      return NextResponse.json(
71→        { error: "Time slot is already held" },
72→        { status: 409 }
73→      );
74→    }
75→
76→    throw error;
77→  }
78→}
79→
80→class HoldError extends Error {
81→  constructor(
82→    public status: number,
83→    message: string
84→  ) {
85→    super(message);
86→  }
87→}
