 4→export async function DELETE(
 5→  request: Request,
 6→  { params }: { params: Promise<{ holdId: string }> }
 7→) {
 8→  const { holdId } = await params;
 9→
10→  let body: { playerEmail?: string };
11→  try {
12→    body = await request.json();
13→  } catch {
14→    return NextResponse.json(
15→      { error: "playerEmail is required" },
16→      { status: 400 }
17→    );
18→  }
19→
20→  const { playerEmail } = body;
21→  if (!playerEmail) {
22→    return NextResponse.json(
23→      { error: "playerEmail is required" },
24→      { status: 400 }
25→    );
26→  }
27→
28→  const hold = await prisma.hold.findUnique({ where: { id: holdId } });
29→
